<script setup>import {ref} from 'vue';import {useRouter} from 'vue-router';import {login} from '../api/http';const router=useRouter(),username=ref('admin'),password=ref('admin123'),submitting=ref(false),errorMessage=ref('');async function submit(){errorMessage.value='';submitting.value=true;try{if(import.meta.env.VITE_DEMO_MODE==='true')localStorage.setItem('zhuatech_bi_token','demo-mode');else await login(username.value,password.value);await router.push('/admin/cockpit')}catch(e){errorMessage.value=e.response?.data?.message||'登录失败，请检查账号、密码和后端服务'}finally{submitting.value=false}}</script>
<template><div class="login-page"><section class="login-story"><div class="login-brand"><span>ZH</span><div><b>ZhuaTech BI</b><small>知华科技商业智能分析平台</small></div></div><div class="story-copy"><p>ONE VIEW · BETTER DECISIONS</p><h1>让每一个指标，<br/>回到统一经营口径。</h1><span>连接销售、供应链、制造、财务和项目数据，把口径一致的洞察交给每一位经营者。</span></div><div class="story-metric"><div><b>4,250 万</b><span>年度营业收入</span></div><div><b>34.4%</b><span>综合毛利率</span></div><div><b>99.2%</b><span>数据任务成功率</span></div></div><footer>上海如静知华信息科技有限公司 · www.zhuatech.cn</footer></section><form @submit.prevent="submit"><p>安全登录</p><h2>进入数据分析中心</h2><label>账号<input v-model="username" autocomplete="username"/></label><label>密码<input v-model="password" type="password" autocomplete="current-password"/></label><div class="form-meta"><span>☑ 保持登录</span><a>无法登录？</a></div><p v-if="errorMessage" class="login-error">{{errorMessage}}</p><button class="button primary" :disabled="submitting">{{submitting?'正在验证…':'登录系统'}}</button><small>演示账号：admin / admin123</small></form></div></template>
